1	import { describe, expect, it, vi } from "vitest";
2	import { WorkerSlot, type IWorkerLike, WorkerManager } from "./worker-manager";
3	
4	function fakeWorker(): IWorkerLike & { listeners: Map<string, Set<(event: unknown) => void>> } {
5	  const listeners = new Map<string, Set<(event: unknown) => void>>();
6	  return {
7	    listeners,
8	    postMessage: vi.fn(),
9	    terminate: vi.fn(),
10	    addEventListener: (type: string, listener: (event: never) => void) => {
11	      let set = listeners.get(type);
12	      if (!set) {
13	        set = new Set();
14	        listeners.set(type, set);
15	      }
16	      set.add(listener as (event: unknown) => void);
17	    },
18	    removeEventListener: (type: string, listener: (event: never) => void) => {
19	      listeners.get(type)?.delete(listener as (event: unknown) => void);
20	    },
21	  } as unknown as IWorkerLike & { listeners: Map<string, Set<(event: unknown) => void>> };
22	}
23	
24	describe("WorkerManager", () => {
25	  it("lazily creates a worker on first use via the registered factory", () => {
26	    const manager = new WorkerManager();
27	    const factory = vi.fn(fakeWorker);
28	    manager.registerFactory(WorkerSlot.Rendering, factory);
29	
30	    expect(manager.has(WorkerSlot.Rendering)).toBe(false);
31	    manager.postMessage(WorkerSlot.Rendering, { hello: true });
32	
33	    expect(factory).toHaveBeenCalledTimes(1);
34	    expect(manager.has(WorkerSlot.Rendering)).toBe(true);
35	  });
36	
37	  it("reuses the same worker instance across calls", () => {
38	    const manager = new WorkerManager();
39	    const factory = vi.fn(fakeWorker);
40	    manager.registerFactory(WorkerSlot.Export, factory);
41	
42	    manager.postMessage(WorkerSlot.Export, { a: 1 });
43	    manager.postMessage(WorkerSlot.Export, { a: 2 });
44	
45	    expect(factory).toHaveBeenCalledTimes(1);
46	  });
47	
48	  it("throws when posting to a slot with no registered factory", () => {
49	    const manager = new WorkerManager();
50	    expect(() => manager.postMessage(WorkerSlot.AIInference, {})).toThrow(
51	      /No worker factory registered/,
52	    );
53	  });
54	
55	  it("onMessage subscribes to the underlying worker and can unsubscribe", () => {
56	    const manager = new WorkerManager();
57	    const worker = fakeWorker();
58	    manager.registerFactory(WorkerSlot.ThumbnailGen, () => worker);
59	    const listener = vi.fn();
60	
61	    const unsubscribe = manager.onMessage(WorkerSlot.ThumbnailGen, listener);
62	    expect(worker.listeners.get("message")?.size).toBe(1);
63	
64	    unsubscribe();
65	    expect(worker.listeners.get("message")?.size).toBe(0);
66	  });
67	
68	  it("route() forwards a message to the destination slot", () => {
69	    const manager = new WorkerManager();
70	    const rendering = fakeWorker();
71	    const exportWorker = fakeWorker();
72	    manager.registerFactory(WorkerSlot.Rendering, () => rendering);
73	    manager.registerFactory(WorkerSlot.Export, () => exportWorker);
74	    manager.postMessage(WorkerSlot.Rendering, {});
75	
76	    manager.route(WorkerSlot.Rendering, WorkerSlot.Export, { frame: 1 });
77	
78	    expect(exportWorker.postMessage).toHaveBeenCalledWith({ frame: 1 }, undefined);
79	  });
80	
81	  it("route() throws when the source slot was never registered", () => {
82	    const manager = new WorkerManager();
83	    manager.registerFactory(WorkerSlot.Export, fakeWorker);
84	
85	    expect(() => manager.route(WorkerSlot.Rendering, WorkerSlot.Export, {})).toThrow(
86	      /unregistered worker slot/,
87	    );
88	  });
89	
90	  it("terminate() disposes the worker and removes it so it can be recreated", () => {
91	    const manager = new WorkerManager();
92	    const first = fakeWorker();
93	    const factory = vi.fn().mockReturnValueOnce(first).mockReturnValue(fakeWorker());
94	    manager.registerFactory(WorkerSlot.Rendering, factory);
95	    manager.postMessage(WorkerSlot.Rendering, {});
96	
97	    manager.terminate(WorkerSlot.Rendering);
98	
99	    expect(first.terminate).toHaveBeenCalledTimes(1);
100	    expect(manager.has(WorkerSlot.Rendering)).toBe(false);
101	
102	    manager.postMessage(WorkerSlot.Rendering, {});
103	    expect(factory).toHaveBeenCalledTimes(2);
104	  });
105	
106	  it("terminateAll() terminates every active worker", () => {
107	    const manager = new WorkerManager();
108	    const rendering = fakeWorker();
109	    const exportWorker = fakeWorker();
110	    manager.registerFactory(WorkerSlot.Rendering, () => rendering);
111	    manager.registerFactory(WorkerSlot.Export, () => exportWorker);
112	    manager.postMessage(WorkerSlot.Rendering, {});
113	    manager.postMessage(WorkerSlot.Export, {});
114	
115	    manager.terminateAll();
116	
117	    expect(rendering.terminate).toHaveBeenCalledTimes(1);
118	    expect(exportWorker.terminate).toHaveBeenCalledTimes(1);
119	  });
120	});

1	import { DEFAULT_TICK_RESOLUTION, PlaybackState, toTick, type Tick } from "@motion-studio/shared";
2	
3	/** Ticks are subdivisions of a frame, so the frame number never depends on fps. */
4	export function tickToFrameNumber(
5	  tick: Tick,
6	  tickResolution: number = DEFAULT_TICK_RESOLUTION,
7	): number {
8	  return Math.floor(tick / tickResolution);
9	}
10	
11	export function frameNumberToTick(
12	  frameNumber: number,
13	  tickResolution: number = DEFAULT_TICK_RESOLUTION,
14	): Tick {
15	  return toTick(frameNumber * tickResolution);
16	}
17	
18	export type FrameRequester = (callback: (time: number) => void) => number;
19	export type FrameCanceller = (handle: number) => void;
20	
21	/**
22	 * The fixed per-frame pipeline from docs/04-core/core-overview.md. This is a
23	 * direct call chain, not an Event Bus dispatch — engines never decide
24	 * execution order themselves, the Scheduler does.
25	 */
26	export interface ISchedulerFrameHandlers {
27	  onAnimationUpdate?(tick: Tick): void;
28	  onTimelineUpdate?(tick: Tick): void;
29	  onSelectionUpdate?(tick: Tick): void;
30	  onAudioSync?(tick: Tick): void;
31	  onRenderFrame?(tick: Tick): void;
32	  onPresentFrame?(tick: Tick): void;
33	}
34	
35	export interface ISchedulerOptions {
36	  tickResolution?: number;
37	  /** Ticks advanced per wall-clock second while playing. Defaults to 30fps * tickResolution. */
38	  ticksPerSecond?: number;
39	  requestFrame?: FrameRequester;
40	  cancelFrame?: FrameCanceller;
41	}
42	
43	const defaultRequestFrame: FrameRequester = (callback) =>
44	  typeof requestAnimationFrame === "function"
45	    ? requestAnimationFrame(callback)
46	    : (setTimeout(() => callback(Date.now()), 1000 / 60) as unknown as number);
47	
48	const defaultCancelFrame: FrameCanceller = (handle) =>
49	  typeof cancelAnimationFrame === "function" ? cancelAnimationFrame(handle) : clearTimeout(handle);
50	
51	/** raf-based tick scheduler driving the preview loop. See PLAN.md Phase 2.3. */
52	export class Scheduler {
53	  private readonly handlers: ISchedulerFrameHandlers;
54	  private readonly tickResolution: number;
55	  private readonly ticksPerSecond: number;
56	  private readonly requestFrame: FrameRequester;
57	  private readonly cancelFrame: FrameCanceller;
58	
59	  private state: PlaybackState = PlaybackState.Idle;
60	  private tick: Tick = toTick(0);
61	  private frameHandle: number | null = null;
62	  private lastFrameTime: number | null = null;
63	
64	  constructor(handlers: ISchedulerFrameHandlers, options: ISchedulerOptions = {}) {
65	    this.handlers = handlers;
66	    this.tickResolution = options.tickResolution ?? DEFAULT_TICK_RESOLUTION;
67	    this.ticksPerSecond = options.ticksPerSecond ?? 30 * this.tickResolution;
68	    this.requestFrame = options.requestFrame ?? defaultRequestFrame;
69	    this.cancelFrame = options.cancelFrame ?? defaultCancelFrame;
70	  }
71	
72	  get playbackState(): PlaybackState {
73	    return this.state;
74	  }
75	
76	  get currentTick(): Tick {
77	    return this.tick;
78	  }
79	
80	  play(): void {
81	    if (this.state === PlaybackState.Playing) {
82	      return;
83	    }
84	    this.state = PlaybackState.Playing;
85	    this.lastFrameTime = null;
86	    this.scheduleNext();
87	  }
88	
89	  pause(): void {
90	    if (this.state !== PlaybackState.Playing) {
91	      return;
92	    }
93	    this.state = PlaybackState.Paused;
94	    this.cancelScheduled();
95	  }
96	
97	  stop(): void {
98	    this.state = PlaybackState.Idle;
99	    this.cancelScheduled();
100	    this.seek(toTick(0));
101	  }
102	
103	  seek(tick: Tick): void {
104	    this.state =
105	      this.state === PlaybackState.Playing ? PlaybackState.Playing : PlaybackState.Seeking;
106	    this.tick = tick;
107	    this.runFramePipeline();
108	    if (this.state === PlaybackState.Seeking) {
109	      this.state = PlaybackState.Idle;
110	    }
111	  }
112	
113	  /** Advances the tick by one wall-clock frame tick and runs the pipeline. Exposed for deterministic testing. */
114	  step(deltaMs: number): void {
115	    const deltaTicks = toTick(Math.round((deltaMs / 1000) * this.ticksPerSecond));
116	    this.tick = toTick(this.tick + deltaTicks);
117	    this.runFramePipeline();
118	  }
119	
120	  private scheduleNext(): void {
121	    this.frameHandle = this.requestFrame((time) => this.onFrame(time));
122	  }
123	
124	  private cancelScheduled(): void {
125	    if (this.frameHandle !== null) {
126	      this.cancelFrame(this.frameHandle);
127	      this.frameHandle = null;
128	    }
129	  }
130	
131	  private onFrame(time: number): void {
132	    if (this.state !== PlaybackState.Playing) {
133	      return;
134	    }
135	    const delta = this.lastFrameTime === null ? 0 : time - this.lastFrameTime;
136	    this.lastFrameTime = time;
137	    this.step(delta);
138	    this.scheduleNext();
139	  }
140	
141	  private runFramePipeline(): void {
142	    const tick = this.tick;
143	    this.handlers.onAnimationUpdate?.(tick);
144	    this.handlers.onTimelineUpdate?.(tick);
145	    this.handlers.onSelectionUpdate?.(tick);
146	    this.handlers.onAudioSync?.(tick);
147	    this.handlers.onRenderFrame?.(tick);
148	    this.handlers.onPresentFrame?.(tick);
149	  }
150	}

1	import type { AppEvent, AppEventMap, AppEventType } from "@motion-studio/shared";
2	
3	export type EventListener<T extends AppEventType> = (event: AppEvent<T>) => void;
4	export type AsyncEventListener<T extends AppEventType> = (
5	  event: AppEvent<T>,
6	) => void | Promise<void>;
7	
8	/**
9	 * Typed publish/subscribe bus for coarse notifications (selection changed,
10	 * export finished, etc). Not the per-frame hot path — see Scheduler for
11	 * that direct call chain. Every listener declares its exact event type;
12	 * there is no wildcard subscription mechanism. See
13	 * docs/04-core/core-overview.md and CLAUDE.md "Canonical names".
14	 */
15	export class EventBus {
16	  private readonly listeners = new Map<AppEventType, Set<AsyncEventListener<AppEventType>>>();
17	
18	  on<T extends AppEventType>(
19	    type: T,
20	    listener: EventListener<T> | AsyncEventListener<T>,
21	  ): () => void {
22	    let set = this.listeners.get(type);
23	    if (!set) {
24	      set = new Set();
25	      this.listeners.set(type, set);
26	    }
27	    set.add(listener as AsyncEventListener<AppEventType>);
28	    return () => this.off(type, listener);
29	  }
